using AeroCompliance.ApiService.Authorization; using AeroCompliance.ApiService.Services; using AeroCompliance.Contracts.Dtos.Common; using AeroCompliance.Contracts.Dtos.Flights; using AeroCompliance.Domain.Entities; using AeroCompliance.Domain.Enums; using AeroCompliance.Infrastructure.Persistence; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AeroCompliance.ApiService.Controllers;
[ApiController,Route("api/flights"),Authorize] public sealed class FlightsController(AeroComplianceDbContext db,ICurrentUserContext user,IAuditService audit):ControllerBase
{
 [HttpGet] public async Task<ActionResult<PagedResponse<FlightSummaryDto>>> List(int page=1,int pageSize=25,Guid? municipalityId=null,Guid? operatorId=null,string? status=null,string? search=null,CancellationToken ct=default){if(!ApiSupport.IsValidPagination(page,pageSize))return Problem(statusCode:400,title:"Invalid pagination");var q=Visible().AsNoTracking();if(user.IsPlatformAdmin&&municipalityId.HasValue)q=q.Where(x=>x.MunicipalityId==municipalityId);if(operatorId.HasValue)q=q.Where(x=>x.DroneOperatorId==operatorId);if(!string.IsNullOrWhiteSpace(status)){if(!TryStatus(status,out var parsed))return Problem(statusCode:400,title:"Invalid flight status");q=q.Where(x=>x.Status==parsed);}var s=ApiSupport.NormalizeSearch(search);if(s is not null)q=q.Where(x=>x.MissionName!=null&&x.MissionName.ToLower().Contains(s));return Ok(await q.OrderByDescending(x=>x.CreatedAt).Select(x=>new FlightSummaryDto(x.Id,x.MunicipalityId,x.DroneOperatorId,x.DroneOperator.FullName,x.MissionName,StatusCode(x.Status),x.ScheduledAt,x.CreatedAt)).ToPagedAsync(page,pageSize,ct));}
 [HttpGet("{id:guid}")] public async Task<ActionResult<FlightDetailsDto>> Get(Guid id,CancellationToken ct){var x=await Visible().AsNoTracking().Include(x=>x.DroneOperator).Include(x=>x.Missions).Include(x=>x.Images).Include(x=>x.Videos).Include(x=>x.Orthomosaics).SingleOrDefaultAsync(x=>x.Id==id,ct);return x is null?NotFound():Ok(Map(x));}
 [HttpPost,Authorize(Policy=Policies.ManageFlights)] public async Task<ActionResult<FlightDetailsDto>> Create(SaveFlightRequest r,CancellationToken ct){if(!ResolveTenant(r.MunicipalityId,out var tenant))return Forbid();var operatorId=user.Role==Roles.DroneOperator?user.UserId:r.DroneOperatorId;if(operatorId is null)return Problem(statusCode:400,title:"Drone operator is required");if(!await ValidOperator(operatorId.Value,tenant,ct))return Problem(statusCode:400,title:"Invalid drone operator",detail:"The operator must be an active DroneOperator in the same municipality.");if(!TryArea(r.PlannedArea,out var area,out var error))return Problem(statusCode:400,title:"Invalid GeoJSON geometry",detail:error);var x=new Flight{Id=Guid.NewGuid(),MunicipalityId=tenant,DroneOperatorId=operatorId.Value,MissionName=r.MissionName?.Trim(),PlannedArea=area,Status=FlightStatus.Planned,ScheduledAt=r.ScheduledAt,WeatherConditions=r.WeatherConditions,QualityFlag=r.QualityFlag,CreatedAt=DateTimeOffset.UtcNow};db.Flights.Add(x);audit.Add("flight.create","Flight",x.Id,after:new{x.MunicipalityId,x.DroneOperatorId,x.MissionName,Status=StatusCode(x.Status),x.ScheduledAt});await db.SaveChangesAsync(ct);return CreatedAtAction(nameof(Get),new{id=x.Id},await ReadDetails(x.Id,ct));}
 [HttpPut("{id:guid}"),Authorize(Policy=Policies.ManageFlights)] public async Task<ActionResult<FlightDetailsDto>> Update(Guid id,SaveFlightRequest r,CancellationToken ct){var x=await Manageable().SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return NotFound();if(x.Status is not FlightStatus.Planned)return Problem(statusCode:409,title:"Conflict",detail:"Only planned flights can be edited.");var operatorId=user.Role==Roles.DroneOperator?user.UserId:r.DroneOperatorId??x.DroneOperatorId;if(operatorId is null||!await ValidOperator(operatorId.Value,x.MunicipalityId,ct))return Problem(statusCode:400,title:"Invalid drone operator");if(!TryArea(r.PlannedArea,out var area,out var error))return Problem(statusCode:400,title:"Invalid GeoJSON geometry",detail:error);var before=new{x.DroneOperatorId,x.MissionName,x.ScheduledAt,x.WeatherConditions,x.QualityFlag};x.DroneOperatorId=operatorId.Value;x.MissionName=r.MissionName?.Trim();x.PlannedArea=area;x.ScheduledAt=r.ScheduledAt;x.WeatherConditions=r.WeatherConditions;x.QualityFlag=r.QualityFlag;audit.Add("flight.update","Flight",id,before,new{x.DroneOperatorId,x.MissionName,x.ScheduledAt,x.WeatherConditions,x.QualityFlag});await db.SaveChangesAsync(ct);return Ok(await ReadDetails(id,ct));}
 [HttpPost("{id:guid}/status-transitions"),Authorize(Policy=Policies.ManageFlights)] public async Task<ActionResult<FlightDetailsDto>> Transition(Guid id,FlightTransitionRequest r,CancellationToken ct){var x=await Manageable().SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return NotFound();if(!TryStatus(r.TargetStatus,out var target))return Problem(statusCode:400,title:"Invalid flight status");if(!Allowed(x.Status,target))return Problem(statusCode:409,title:"Invalid flight transition",detail:$"{StatusCode(x.Status)} cannot transition to {StatusCode(target)}.");var before=StatusCode(x.Status);x.Status=target;var now=DateTimeOffset.UtcNow;if(target==FlightStatus.InProgress)x.StartedAt=now;if(target is FlightStatus.Completed or FlightStatus.Aborted)x.EndedAt=now;if(target==FlightStatus.FlaggedLowQuality)x.QualityFlag=false;audit.Add("flight.status_change","Flight",id,new{Status=before},new{Status=StatusCode(target),Reason=r.Reason?.Trim()});await db.SaveChangesAsync(ct);return Ok(await ReadDetails(id,ct));}
 [HttpGet("{id:guid}/missions")] public async Task<ActionResult<PagedResponse<FlightMissionDto>>> Missions(Guid id,int page=1,int pageSize=25,CancellationToken ct=default){if(!ApiSupport.IsValidPagination(page,pageSize))return Problem(statusCode:400,title:"Invalid pagination");if(!await Visible().AnyAsync(x=>x.Id==id,ct))return NotFound();return Ok(await db.FlightMissions.AsNoTracking().Where(x=>x.FlightId==id).OrderBy(x=>x.Id).Select(x=>new FlightMissionDto(x.Id,x.FlightId,x.Purpose,x.AltitudeM,x.OverlapPercent,x.Notes)).ToPagedAsync(page,pageSize,ct));}
 [HttpPost("{id:guid}/missions"),Authorize(Policy=Policies.ManageFlights)] public async Task<ActionResult<FlightMissionDto>> CreateMission(Guid id,CreateFlightMissionRequest r,CancellationToken ct){var flight=await Manageable().SingleOrDefaultAsync(x=>x.Id==id,ct);if(flight is null)return NotFound();if(flight.Status!=FlightStatus.Planned)return Problem(statusCode:409,title:"Conflict",detail:"Missions can only be added to planned flights.");var x=new FlightMission{Id=Guid.NewGuid(),FlightId=id,Purpose=r.Purpose?.Trim(),AltitudeM=r.AltitudeM,OverlapPercent=r.OverlapPercent,Notes=r.Notes?.Trim()};db.FlightMissions.Add(x);audit.Add("flight_mission.create","FlightMission",x.Id,after:new{x.FlightId,x.Purpose,x.AltitudeM,x.OverlapPercent});await db.SaveChangesAsync(ct);return Created($"/api/flights/{id}/missions",new FlightMissionDto(x.Id,x.FlightId,x.Purpose,x.AltitudeM,x.OverlapPercent,x.Notes));}
 private IQueryable<Flight> Visible()=>user.IsPlatformAdmin?db.Flights:db.Flights.Where(x=>x.MunicipalityId==user.MunicipalityId);private IQueryable<Flight> Manageable(){var q=Visible();return user.Role==Roles.DroneOperator?q.Where(x=>x.DroneOperatorId==user.UserId):q;}private bool ResolveTenant(Guid? requested,out Guid tenant){tenant=user.IsPlatformAdmin?requested??Guid.Empty:user.MunicipalityId??Guid.Empty;return tenant!=Guid.Empty;}private Task<bool> ValidOperator(Guid id,Guid tenant,CancellationToken ct)=>db.Users.AnyAsync(x=>x.Id==id&&x.MunicipalityId==tenant&&x.IsActive&&x.Role.Name==Roles.DroneOperator,ct);private static bool TryArea(System.Text.Json.JsonElement? json,out NetTopologySuite.Geometries.MultiPolygon? area,out string error){area=null;error="";if(json is null||json.Value.ValueKind is System.Text.Json.JsonValueKind.Null or System.Text.Json.JsonValueKind.Undefined)return true;if(!GeoJsonService.TryReadMultiPolygon(json.Value,out var parsed,out error))return false;area=parsed;return true;}private async Task<FlightDetailsDto?> ReadDetails(Guid id,CancellationToken ct){var x=await db.Flights.AsNoTracking().Include(x=>x.DroneOperator).Include(x=>x.Missions).Include(x=>x.Images).Include(x=>x.Videos).Include(x=>x.Orthomosaics).SingleOrDefaultAsync(x=>x.Id==id,ct);return x is null?null:Map(x);}private static FlightDetailsDto Map(Flight x)=>new(x.Id,x.MunicipalityId,x.DroneOperatorId,x.DroneOperator?.FullName,x.MissionName,x.PlannedArea is null?null:GeoJsonService.Write(x.PlannedArea),StatusCode(x.Status),x.ScheduledAt,x.StartedAt,x.EndedAt,x.WeatherConditions,x.QualityFlag,x.Missions.Count,x.Images.Count,x.Videos.Count,x.Orthomosaics.Count,x.CreatedAt);private static bool Allowed(FlightStatus from,FlightStatus to)=>(from,to) is (FlightStatus.Planned,FlightStatus.InProgress)or(FlightStatus.Planned,FlightStatus.Aborted)or(FlightStatus.InProgress,FlightStatus.Completed)or(FlightStatus.InProgress,FlightStatus.Aborted)or(FlightStatus.Completed,FlightStatus.FlaggedLowQuality);private static bool TryStatus(string value,out FlightStatus status){var n=value.Trim().Replace("-","_").ToLowerInvariant();status=n switch{"planned"=>FlightStatus.Planned,"in_progress" or "inprogress"=>FlightStatus.InProgress,"completed"=>FlightStatus.Completed,"aborted"=>FlightStatus.Aborted,"flagged_low_quality" or "flaggedlowquality"=>FlightStatus.FlaggedLowQuality,_=>(FlightStatus)(-1)};return Enum.IsDefined(status);}private static string StatusCode(FlightStatus s)=>s switch{FlightStatus.Planned=>"planned",FlightStatus.InProgress=>"in_progress",FlightStatus.Completed=>"completed",FlightStatus.Aborted=>"aborted",FlightStatus.FlaggedLowQuality=>"flagged_low_quality",_=>"unknown"};
}
